/**
 * Get current UI language
 * @returns {Promise<string>} Language code (default: 'en')
 */
export async function getUILanguage() {
  try {
    const result = await chrome.storage.local.get(['ui_language']);
    if (typeof result.ui_language === 'string' && Object.hasOwn(UI_LOCALES, result.ui_language)) return result.ui_language;
  } catch {}
  try {
    const browserLanguage = chrome.i18n?.getUILanguage?.() || 'en';
    const base = browserLanguage.toLowerCase().split(/[-_]/)[0];
    const language = base === 'uk' ? 'ua' : base;
    return Object.hasOwn(UI_LOCALES, language) ? language : 'en';
  } catch { return 'en'; }
}

/**
 * Set UI language
 * @param {string} langCode - Language code
 */
export async function setUILanguage(langCode) {
  try {
    await chrome.storage.local.set({ ui_language: langCode });
  } catch (error) {
    // Use console.error here as this is a utility module that may be imported before logging is initialized
    // In practice, this error is rare and logging is acceptable
    console.error('Failed to set UI language:', error);
  }
}

/**
 * Get localized string
 * @param {string} key - Translation key
 * @param {string} langCode - Optional language code (defaults to current UI language)
 * @param {Record<string, unknown>} [params={}] - Message values
 * @returns {Promise<string>} Localized string
 */
export async function t(key, langCode = null, params = {}) {
  const lang = langCode || await getUILanguage();
  return formatMessage(key, lang, params);
}

/**
 * Get localized string synchronously (requires langCode)
 * @param {string} key - Translation key
 * @param {string} langCode - Language code
 * @param {Record<string, unknown>} [params={}] - Message values
 * @returns {string} Localized string
 */
export function tSync(key, langCode, params = {}) {
  return formatMessage(key, langCode, params);
}

export function formatStatusUpdate(key, langCode, params = {}) {
  return { status: formatMessage(key, langCode, params), statusTranslationKey: key, statusTranslationParams: params };
}

/** Map stored UI language codes to language tags used by HTML and Intl. */
export function getLocaleTag(langCode) {
  const code = getLocaleCode(langCode);
  return code === 'ua' ? 'uk' : code;
}

function getLocaleCode(langCode) {
  const base = typeof langCode === 'string' ? langCode.toLowerCase().split(/[-_]/)[0] : 'en';
  const code = base === 'uk' ? 'ua' : base;
  return Object.hasOwn(UI_LOCALES, code) ? code : 'en';
}

/**
 * Format a translated message without interpreting its values as markup.
 * @param {string} key
 * @param {string} langCode
 * @param {Record<string, unknown>} [params]
 */
export function formatMessage(key, langCode, params = {}) {
  const locale = UI_LOCALES[getLocaleCode(langCode)];
  const values = params && typeof params === 'object' ? params : {};
  const plural = Object.hasOwn(values, 'count') && typeof values.count === 'number' && Number.isFinite(values.count)
    ? new Intl.PluralRules(getLocaleTag(langCode)).select(values.count) : null;
  const pluralKey = plural ? `${key}_${plural}` : key;
  const ownString = (dictionary, name) => Object.hasOwn(dictionary, name) && typeof dictionary[name] === 'string' ? dictionary[name] : '';
  const template = ownString(locale, pluralKey) || ownString(locale, key) || ownString(UI_LOCALES.en, pluralKey) || ownString(UI_LOCALES.en, key) || key;
  return template.replace(/\{(\w+)\}/g, (placeholder, name) =>
    Object.hasOwn(values, name) ? String(values[name]) : placeholder);
}

